前処理スクリプト:
// 署名の生成例: USER_ID + TIMESTAMP の SHA-256（16進）を変数 SIGNATURE に設定
String src = (vars.get('USER_ID') ?: '') + (vars.get('TIMESTAMP') ?: '')
def digest = java.security.MessageDigest.getInstance('SHA-256').digest(src.getBytes('UTF-8'))
vars.put('SIGNATURE', digest.encodeHex().toString())

後処理スクリプト:
// 応答 JSON の解析例: 値を取り出して次の API で使う変数に設定
try {
    def json = new groovy.json.JsonSlurper().parseText(prev.getResponseDataAsString())
    vars.put('LOGIN_USER', String.valueOf(json?.json?.userId))
} catch (Exception e) {
    log.warn('ログイン応答の解析に失敗しました: ' + e.getMessage())
}
